// === Tab: mySketch ===
//Code and palettes by Aaron Reuland
//For the #wccChallenge on the theme of 'Greek Mythology'.
//The pallettes are based on the colorings of 10 real snakes (got thoroughly annoyed at having to sort 
//through so many AI fakes to find genuine photos).
//with 4 different patterns & 10 different palettes(shuffled each time), there's a fair amount of variation.

let palettes = [
	['#34221b', '#d5c4b2', '#937f6b'],
	['#4c4846', '#dabe9f', '#b63325'],
	['#272013', '#95c30f', '#a5af30', '#c7b3a9'],
	['#d8bbbc', '#d2413a', '#f1d9bc'],
	['#29241c', '#c39117', '#c56b01'],
	['#3a1815', '#b23412', '#4b7877', '#cbc7a4'],
	['#3f2b25', '#f0aa33', '#bc3915'],
	['#ee951e', '#fce9c1', '#291d17'],
	['#d6af7d', '#2a1911', '#8d5226'],
	['#b7e8ef', '#217691', '#3e1b1b', '#f3ecfa']
]

let hairW, y, simplex, colors, shade, stripeColor, nonShade, patternChooser

function setup() {
	createCanvas(windowHeight * 0.66, windowHeight);
	background("#10130F");
	colors = random(palettes)
	simplex = new openSimplexNoise(Date.now())
	hairW = width / 15
	y = -hairW
	shade = color(0)
	nonShade = color(255, 0)
	noStroke()
	shuffle(colors, true)


	patternChooser = floor(random(4))
	if (patternChooser < 2) {
		let stripeColorIndex = floor(random(colors.length))
		stripeColor = colors[stripeColorIndex]
		colors.splice(stripeColorIndex, 1)
	}
}

function draw() {

	if (y < height + hairW + height / 10) {
		y += 0.5
		for (let baseX = -width / 4; baseX < width / 2; baseX += hairW * 0.66) {
			if (floor(baseX + y) % 5 == 0) {
				stroke(0, 20)
			} else {
				noStroke()
			}

			//patterns: 0= vstripes, 1= hvstripes, 2=hstripes, 3=splotch	
			switch (patternChooser) {
				case 0:
					vstripes(baseX, y);
					break;
				case 1:
					vhstripes(baseX, y, 35);
					break;
				case 2:
					hstripes(baseX, y, 35);
					break;
				case 3:
					splotch(baseX, y)
			}
		}
	}
}

function hstripes(baseX, y, sw) {

	let xoff = simplex.noise2D(baseX / 50, y / 100) * width / 4
	let yoff = noise(baseX + xoff / 50, y / 100) * 30
	let ci = floor(abs(baseX / 100 + (y / sw)) % colors.length)
	let c1 = colors[ci]
	let coloring = drawingContext.createRadialGradient(baseX + xoff, y, 1, baseX + xoff, y + yoff, hairW)
	//let c1=stripes(baseX, y, 35)
	coloring.addColorStop(0, c1)
	coloring.addColorStop(1, shade)
	drawingContext.fillStyle = coloring
	ellipse(baseX + xoff, y + yoff, hairW, hairW / 3)

	let coloring2 = drawingContext.createRadialGradient(width - baseX - xoff, y, 1, width - baseX - xoff, y + yoff, hairW)
	coloring2.addColorStop(0, c1)
	coloring2.addColorStop(1, shade)
	drawingContext.fillStyle = coloring2
	ellipse(width - baseX - xoff, y + yoff, hairW, hairW / 3)

}


function vhstripes(baseX, y, sw) {
	let sColor = stripeColor
	var xoff = simplex.noise2D(baseX / 50, y / 100) * width / 4
	var yoff = noise(baseX + xoff / 50, y / 100) * 30
	var ci = floor(abs(baseX / 100 + (y / sw)) % colors.length)
	var c1 = colors[ci]
	push()
	var coloring = drawingContext.createRadialGradient(baseX + xoff, y, 1, baseX + xoff, y + yoff, hairW)
	coloring.addColorStop(0, c1)
	coloring.addColorStop(1, shade)
	drawingContext.fillStyle = coloring
	ellipse(baseX + xoff, y + yoff, hairW, hairW / 3)
	pop()
	fill(sColor)
	rectMode(CENTER)
	rect(baseX + xoff, y + yoff, hairW / 5, hairW / 3)


	push()
	var coloring2 = drawingContext.createRadialGradient(width - baseX - xoff, y, 1, width - baseX - xoff, y + yoff, hairW)
	coloring2.addColorStop(0, c1)
	coloring2.addColorStop(1, shade)
	drawingContext.fillStyle = coloring2
	ellipse(width - baseX - xoff, y + yoff, hairW, hairW / 3)
	pop()
	fill(sColor)
	rectMode(CENTER)
	rect(width - baseX - xoff, y + yoff, hairW / 5, hairW / 3)

}


function vstripes(baseX, y) {
	var sColor = stripeColor
	var xoff = simplex.noise2D(baseX / 50, y / 100) * width / 4
	var yoff = noise(baseX + xoff / 50, y / 100) * 30
	var c1 = colors[1]
	push()
	var coloring = drawingContext.createRadialGradient(baseX + xoff, y, 1, baseX + xoff, y + yoff, hairW)
	coloring.addColorStop(0, c1)
	coloring.addColorStop(1, shade)
	drawingContext.fillStyle = coloring
	ellipse(baseX + xoff, y + yoff, hairW, hairW / 3)
	pop()
	fill(sColor)
	rectMode(CENTER)
	rect(baseX + xoff, y + yoff, hairW / 5, hairW / 3)


	push()
	var coloring2 = drawingContext.createRadialGradient(width - baseX - xoff, y, 1, width - baseX - xoff, y + yoff, hairW)
	coloring2.addColorStop(0, c1)
	coloring2.addColorStop(1, shade)
	drawingContext.fillStyle = coloring2
	ellipse(width - baseX - xoff, y + yoff, hairW, hairW / 3)
	pop()
	fill(sColor)
	rectMode(CENTER)
	rect(width - baseX - xoff, y + yoff, hairW / 5, hairW / 3)

}


function splotch(baseX, y) {

	var xoff = simplex.noise2D(baseX / 50, y / 100) * width / 4
	var yoff = noise(baseX + xoff / 50, y / 100) * 30
	push()
	let cOff = simplex.noise2D(baseX + xoff / 50, y / 10) * hairW
	var coloring = drawingContext.createRadialGradient(baseX + xoff, y, 1, baseX + xoff + cOff, y + yoff, hairW)
	var c1 = colors[0]
	let c2 = colors[1]
	let c3 = colors[2]
	coloring.addColorStop(0, c1)
	coloring.addColorStop(0.3, c2)
	coloring.addColorStop(0.8, c3)
	drawingContext.fillStyle = coloring
	ellipse(baseX + xoff, y + yoff, hairW, hairW / 3)
	pop()
	push()
	blendMode(DARKEST)
	let shading = drawingContext.createRadialGradient(baseX + xoff, y, 1, baseX + xoff, y + yoff, hairW)
	shading.addColorStop(0, nonShade)
	shading.addColorStop(0.9, shade)
	drawingContext.fillStyle = shading
	ellipse(baseX + xoff, y + yoff, hairW, hairW / 3)
	pop()

	push()
	var coloring2 = drawingContext.createRadialGradient(width - baseX - xoff, y, 1, width - baseX - xoff + cOff, y + yoff, hairW)
	coloring2.addColorStop(0, c1)
	coloring2.addColorStop(0.3, c2)
	coloring2.addColorStop(0.8, c3)
	drawingContext.fillStyle = coloring2
	ellipse(width - baseX - xoff, y + yoff, hairW, hairW / 3)
	pop()
	push()
	blendMode(DARKEST)
	shading2 = drawingContext.createRadialGradient(width - baseX - xoff, y, 1, width - baseX - xoff, y + yoff, hairW)
	shading2.addColorStop(0, nonShade)
	shading2.addColorStop(0.9, shade)
	drawingContext.fillStyle = shading2
	ellipse(width - baseX - xoff, y + yoff, hairW, hairW / 3)
	pop()
}

